window.TEXTP = window.TEXTP || {};
window.TEXTP["49.7"] = [[["p","Затем его вознесли на ближнее небо и (Джибриль) постучал в одни из врат этого неба, после чего обитатели неба обратились к нему: <i>«Кто это?!». </i>Он ответил: <i>«Это – Джибриль». </i>Они спросили: <i>«А кто с тобой?». </i>Он ответил: <i>«Мухаммад». </i>Они спросили: <i>«За ним уже послали?». </i>Джибриль ответил: <i>«Да». </i>Они сказали: <i>«Добро пожаловать!». </i>Обитатели небес обрадовались его (приходу). При этом обитатели небес не знали, чего Аллах желает посредством него на земле, пока Он не сообщил им."],["p","На ближнем небе он обнаружил Адама, и Джибриль сказал ему: <i>«Это – твой праотец Адам. Поприветствуй же его!». </i>(Пророк, да благословит его Аллах и приветствует), поприветствовал его, а (Адам) ответил ему и сказал: <i>«Добро пожаловать, о мой сын! Ты – прекрасный сын!». </i>Затем на ближнем небе он увидел две текущие реки и спросил: <b><i>«Что это за две реки, о Джибриль?». </i></b>(Джибриль) ответил: <i>«Это – истоки Нила и Евфрата». </i>Затем они пошли дальше и увидели другую реку, возле которой был дворец из жемчуга и драгоценных камней. (Пророк, да благословит его Аллах и приветствует), стал нюхать почву, и оказалось, что она пахнет мускусом. Он спросил: <b><i>«О Джибриль! Что это за река?». </i></b>(Джибриль) ответил: <i>«Это – аль-Каусар, который припас для тебя твой Господь!». </i>"],["p","Затем (Джибриль) поднял его на второе небо, и ангелы сказали ему то же самое, что сказали ангелы на первом небе: <i>«А кто с тобой?». </i>Он ответил: <i>«Мухаммад».</i> Они спросили: <i>«За ним уже послали?». </i>Джибриль ответил: <i>«Да». </i>Они сказали: <i>«Добро пожаловать!». </i>"],["p","Затем (Джибриль) поднял его на третье небо, и ангелы сказали ему то же самое, что сказали ангелы на первом и втором небе. Затем (Джибриль) поднял его на четвертое небо, где ангелы спросили у него то же самое. Затем (Джибриль) поднял его на пятое небо, где ангелы спросили у него то же самое. Затем (Джибриль) поднял его на шестое небо, где ангелы спросили у него то же самое. Затем (Джибриль) поднял его на седьмое небо, где ангелы спросили у него то же самое. И на каждом небе были пророки, имена которых он назвал, а я<sup class=\"fn\">605</sup> запомнил среди них, что Идрис был на втором небе, Харун – на четвертом, ещё один был на пятом, но я не запомнил его имени, на шестом – Ибрахим, а на седьмом – Муса, ибо он говорил с Аллахом."],["n",[[605,"Это слова передатчика этого хадиса от Анаса."]]],["p","Муса сказал: <i>«Господи! Я не думал, что кого-то поднимут выше меня!». </i>Но (пророка Мухаммада) подняли выше настолько, насколько знает только Аллах, пока он не дошёл до лотоса крайнего предела (сидрат аль-мунтаха). <b>И тогда Могущественный Господь величия приблизился и снизошёл так, что оказался от него на расстоянии двух полетов стрелы и даже еще ближе, и внушил Он откровением Своему рабу то, что пожелал</b><sup class=\"fn\">606</sup>, и среди того, что Он внушил ему, было вменение в обязанность для его общины пятидесяти молитв в течение дня и ночи. Затем (пророк, да благословит его Аллах и приветствует), спустился и дошёл до Мусы, который спросил: <i>«О Мухаммад! Что завещал тебе Господь твой?!». </i>Он ответил: <b><i>«Он завещал для (членов) моей общины пятьдесят молитв в течение дня и ночи». </i></b>(Муса) сказал: <i>«Воистину, твоя община не сможет! Возвращайся, и пусть твой Господь облегчит тебе и им!». </i>(Пророк, да благословит его Аллах и приветствует), посмотрел на Джибриля, словно советуясь с ним, и Джибриль сделал ему знак, означавший согласие, если он сам пожелает это."],["n",[[606,"Именно ради этих слов автор книги (да помилует его Аллах) привёл этот длинный хадис."]]]],[["p","Затем Джибриль вновь вознёс его и привел к Могучему (Аллаху), Который находился на Своём месте. (Пророк, да благословит его Аллах и приветствует), сказал: <b><i>«О Господи! Облегчи нам, ведь, поистине, (члены) моей общины не сумеют соблюдать это!». </i></b>Тогда (Аллах) снял с него десять молитв, и (пророк, да благословит его Аллах и приветствует), не переставал ходить от Мусы к своему Господу, пока количество молитв не дошло до пяти. После этого (Муса) вновь остановил его и сказал: <i>«О Мухаммад! Клянусь Аллахом, я вернулся к потомкам Исраиля с ещё более меньшим количеством, чем эти пять, но они погубили эти (молитвы) и оставили их. Твоя община слабее физически, слабее сердцем, взором и слухом. Возвращай ся же, и пусть твой Господь облегчит тебе». </i>В это время (пророк, да благословит его Аллах и приветствует, опять) посмотрел на Джибриля, чтобы тот указал ему, и Джибриль не выразил неодобрение. Он вновь поднял его, и (пророк, да благословит его Аллах и приветствует), сказал: <b><i>«О Господь мой! Поистине, (члены) моей общины слабы телами, сердцами, взором и слухом. Облегчи же нам!». </i></b>Могучий (Аллах) сказал: <b><i>«О Мухаммад!». </i></b>Он ответил: <b><i>«Вот я перед Тобой и счастлив служить Тебе!». </i></b>(Аллах) сказал: <b><i>«Поистине, Моё слово не будет изменено! Всё будет так, как Я предписал тебе в матери Писания</i></b><sup class=\"fn\">607</sup><b><i>! Ты получишь за каждое благое дело десятикратное воздаяние. В матери Писания этих молитв будет пятьдесят, а у тебя их будет пять!». </i></b>"],["n",[[607,"Речь идёт о Хранимой скрижали."]]],["p","(Пророк, да благословит его Аллах и приветствует), вернулся к Мусе и тот спросил: <i>«Ну что ты сделал?». </i>Он ответил: <b><i>«Он облегчил нам и даровал за каждое благое деяние десятикратное воздаяние!». </i></b>(Муса) сказал: <i>«Клянусь Аллахом, я вернулся к потомкам Исраиля с ещё более меньшим, чем это, но они оставили (молитву). Возвращайся, и пусть Он облегчит тебе ещё!». </i>(Пророк, да благословит его Аллах и приветствует), сказал: <b><i>«Клянусь Аллахом, я уже стесняюсь ходить столько раз к своему Всемогущему и Великому Господу!». </i></b>(Тогда Джибриль) сказал (ему): <i>«Спускайся с именем Аллаха!», </i>и тогда он проснулся в Заповедной мечети<sup class=\"fn\">608</sup>."],["n",[[608,"Аль-Бухари, 7517; Муслим, 162; Ибн Манда в «аль-Иман», 712; аль-Лялякаи в «И′тикад ахли ссунна», 1423."]]],["p","472 ― ′Аббад ибн Мансур рассказывал: <i>«Однажды я спросил аль-Хасана (аль-Басри): «(Слова Аллаха): </i><b>\"Потом он приблизился и спустился\"</b><sup class=\"fn\">609</sup>. <i>О ком речь, о Абу Са′ид?». Он ответил: \"О моём Господе!\"».</i>"],["n",[[609,"Сура «ан-Наджм», аят 8."]]],["p","473 ― [Под этим номером приведено то же самое сообщение, что и под № 471]."],["p","Следует заметить, что аль-Уалид ибн Муслим передал сообщение, которое считают достоверным многие искатели знаний из числа таких, кто не понимает науку о скрытых недостатках хадисов. Но у учёных, являющихся знатоками хадисов, это сообщение не является достоверным. Я разъясню его недостатки, если Аллах окажет мне содействие в этом, дабы некоторые люди, изучающие хадисы, не обольщались этим сообщением, и чтобы достоверные хадисы для них не спутались с недостоверными. Я уже не раз говорил, что не считаю дозволенным обманывать искателей знаний, приводя в качестве довода слабые сообщения. Я боюсь своего Великого и Возвышенного Творца, (Который может наказать меня), если я буду обманывать искателей знаний, приводя в качестве довода слабые сообщения, даже если эти сообщения поддерживают мои убеждения<sup class=\"fn\">610</sup>."],["n",[[610,"Следует отметить, что обладатели знания сильно разногласили в достоверности этого хадиса, так как он передан по многочисленным путям передачи от многих сподвижников, но в каждой из этих цепочек есть слабость. Именно поэтому многие обладатели знания назвали этот хадис слабым и запутанным. Среди них, например, имам Ахмад, ад-Даракутни, Ибн Хузейма, аль-′Укейли, Мухаммад ибн Наср аль-Маруази, аль-Хатыб аль-Багдади, аль-Бейхакы, Ибн уль-Джаузи и другие. При этом были и те, кто называл его достоверным. Например, аль-Бухари, ат-Тирмизи, Ибн Теймия и аль-Альбани. А Аллах знает лучше!"]]]],[["p","474 ― Аль-Уалид передал по своей цепочке со слов ′Абд ур-Рахмана ибн ′Аиша аль-Хадрами, который слышал, как посланник Аллаха (да благословит его Аллах и приветствует) говорил: <b><i>«Я видел своего Господа в самом прекрасном образе, и Он сказал (мне): \"О чём спорят в высшем обществе</i></b><sup class=\"fn\">611</sup><b><i>, о Мухаммад?\". Я ответил: \"Я не знаю, о Господь мой! (Я не знаю), о Господь мой!\". Тогда Он положил Свою ладонь между моими лопатками, и я даже почувствовал ее холод между своих сосков, и именно тогда я узнал о том, что на небесах и на земле», </i></b>затем он прочитал (слова Аллаха): <b>«Так Мы показали Ибрахиму царство небес и земли, дабы он стал одним из убежденных»</b><sup class=\"fn\">612</sup>."],["n",[[611,"То есть среди приближённых ангелов."],[612,"Сура «аль-Ан′ам», аят 75."]]],["p","(Далее пророк, да благословит его Аллах и приветствует, продолжил): <b><i>«(Аллах вновь) спросил: \"О чём спорят в высшем обществе, о Мухаммад?\". Я ответил: \"О том, что искупает (грехи), о Господь мой!\". Он спросил: \"И что же это?\". Я ответил: \"Отправление пешком на пятничные молитвы, сидение в мечетях, ожидание молитв и полноценное совершение омовения, даже если это доставляет неудобства (из-за холода)\". Аллах сказал: \"Кто делал это, тот будет жить во благе и умрёт во благе, и у него (останется) столько прегрешений, сколько было у него в тот день, когда его родила мать. А (следующие дела возвышают по) степеням: кормление едой, (произнесение) благих слов, и чтобы ты проводил ночи в молитвах, когда люди спят\". О Аллах! Поистине, я прошу Тебя о благах, о (помощи) в оставлении порицаемого, о любви к беднякам и чтобы Ты принял моё покаяние, простил мне и помиловал меня, а если Ты пожелаешь подвергнуть людей испытанию, то упокой меня избежавшим его!». </i></b>После этого посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Запомните их! Клянусь Тем, в Чьей руке моя душа, они – истина!»</i></b><sup class=\"fn\">613</sup>."],["n",[[613,"Ад-Дарими, 2149; Ибн Аби ′Асым в «ас-Сунна», 467; аль-Аджурри в «аш-Шари′а», 1100; Ибн Джарир в «Тафсире», 5/241."]]],["p","В этом хадисе пришло, что ′Абд ур-Рахман ибн ′Аиш аль-Хадрами сказал: <i>«Я слышал, как посланник Аллаха (да благословит его Аллах и приветствует) говорил», </i>но это является оплошностью, ибо ′Абд ур-Рахман ибн ′Аиш не слышал от пророка (да благословит его Аллах и приветствует) эту историю. На самом деле, он передавал её от одного из сподвижников пророка (да благословит его Аллах и приветствует). Но я считаю, что он не слышал хадис даже от этого сподвижника<sup class=\"fn\">614</sup>."],["n",[[614,"Далее автор книги (да помилует его Аллах) будет приводить разные пути передачи этого хадиса, пытаясь доказать, что ′Абд ур-Рахман ибн ′Аиш передавал его от сподвижника через еще одного передатчика, который был между ними, а не напрямую. Мы сократили перевод этого блока книги, так как автор упоминает один и тот же хадис, но с разными цепочками передачи. Следует также отметить, что аль-Альбани (да помилует его Аллах) сказал в «Зыляль аль-джанна», 1/180: <i>«Хадис достоверный. Его передатчики являются крепкими, но достоверно не установлено, что Ибн ′Аиш был сподвижником». </i>"]]]],[["p","Дело в том, что Яхья ибн Аби Касир передал этот хадис от Зейда ибн Салляма, а тот – от ′Абд ур-Рахмана аль-Хадрами, который передавал от Малика ибн Юхамира, а тот – от Му′аза. А Язид ибн Джабир сказал: «От Халида ибн уль-Ляджляджа, который передавал от ′Абд ур-Рахмана ибн ′Аиша, а тот – от одного из сподвижников пророка (да благословит его Аллах и приветствует)»."],["p","475 ― Также нам рассказал Абу Муса Мухаммад ибн уль-Мусанна, которому рассказал Абу ′Амир ′Абд уль-Малик ибн ′Амр, а ему рассказал Зухейр ибн Мухаммад от Язида ибн Джабира, а тот – от Халида ибн уль-Ляджляджа, который передавал от ′Абд ур-Рахмана ибн ′Аиша, что один из сподвижников пророка (да благословит его Аллах и приветствует) рассказывал: <i>«Однажды к нам вышел пророк (да благословит его Аллах и приветствует)…», </i>и далее упомянут длинный хадис<sup class=\"fn\">615</sup>."],["n",[[615,"Ахмад, 5/378; ′Абдуллах ибн Ахмад в «ас-Сунна», 1209."]]],["p","476 ― Но Му′аз ибн Хишам передавал этот хадис от своего отца, а тот – от Катады, который передавал от Абу Кылябы, а тот – от Халида ибн уль-Ляджляджа, который передавал от ′Абдуллаха ибн ′Аббаса (да будет доволен Аллах им и его отцом)<sup class=\"fn\">616</sup>."],["n",[[616,"Ат-Тирмизи, 3234; Абу Я′ля, 2608; аль-Аджурри в «аш-Шари′а», 1098; ат-Табарани в «ад-Ду′а», 1/420."]]],["p","477 ― Также этот хадис передал Ма′мар от Аюба, а тот – от Абу Кылябы, который передавал от ′Абдуллаха ибн ′Аббаса (да будет доволен Аллах им и его отцом)<sup class=\"fn\">617</sup>."],["n",[[617,"Ат-Тирмизи, 3233; ′Абд ибн Хумейд, 682 и др."]]],["p","Версии, в которых этот хадис передан от ′Абд ур-Рахмана ибн ′Аиша, являются более достоверными, чем те, в которых он передан от ′Абдуллаха ибн ′Аббаса (да будет доволен Аллах им и его отцом)."],["p","478 ― Также этот хадис передан от Яхьи ибн Аби Касира, который передавал от Зейда ибн Салляма, которому рассказал ′Абд ур-Рахман аль-Хадрами (а это Ибн ′Аиш, если пожелает Всевышний Аллах), а ему рассказал Малик ибн Юхамир ас-Саксаки от Му′аза ибн Джабаля (да будет доволен им Аллах)<sup class=\"fn\">618</sup>."],["n",[[618,"Ат-Тирмизи, 3235; Ахмад, 5/243; ат-Табарани в «аль-Кабир», 20/109 и др."]]],["p","479 ― Также этот хадис передал Му′ауия ибн Салих от Абу Яхьи, которого звали Сулейман или Сулейм ибн ′Амир, и он передавал от Абу Язида, а тот – от Абу Салляма аль-Хабаши, который слышал этот хадис от Саубана, вольноотпущенника посланника Аллаха (да благословит его Аллах и приветствует). Но я не знаю, чтобы кто-то критиковал или хвалил этого Абу Язида."],["p","480 ― Также этот хадис передал один шейх из Куфы по имени Са′ид ибн Сувейд аль-Кураши от ′Абд ур-Рахмана ибн Исхака, а тот – от ′Абд ур-Рахмана ибн Аби Лейли, который передавал от Му′аза ибн Джабаля (да будет доволен им Аллах)."]],[["p","Но я не знаю, чтобы кто-то критиковал или хвалил этого Са′ида ибн Сувейда. А этот ′Абд ур-Рахман ибн Исхак Абу Шейба аль-Куфи является слабым передатчиком. К тому же ′Абд ур-Рахман ибн Аби Лейля не слышал хадисы от Му′аза ибн Джабаля. Му′аз (да будет доволен им Аллах) скончался в Шаме в начале правления ′Умара ибн уль-Хаттаба (да будет доволен им Аллах). Он скончался вместе с целой группой других сподвижников пророка (да благословит его Аллах и приветствует). Среди них Биляль ибн Рабах, вольноотпущенник Абу Бакра. Они скончались во время чумы ′Амуас. Я видел их могилы или некоторые из них недалеко от ′Амуаса между Рамлей и Иерусалимом. Если идти из Рамли в Иерусалим, то они будут по правую сторону дороги."],["p","Но все эти хадисы не являются достоверными. Некоторые люди, которые не обладают глубокими знаниями, могут подумать, что хадис, который передал Яхья ибн Аби Касир от Зейда ибн Салляма, является достоверным, ведь он сказал, что Зейду рассказал этот хадис ′Абд ур-Рахман аль-Хадрами. Но Яхья ибн Аби Касир (да помилует его Аллах) занимался тадлисом<sup class=\"fn\">619</sup>, и здесь он не сказал, что слышал этот хадис от Зейда ибн Салляма."],["n",[[619,"То есть иногда не упоминал тех, от кого слышал этот хадис непосредственно, пропуская их в цепочке."]]],["p","481 ― Хусейн аль-Му′аллим рассказывал: <i>«Когда к нам прибыл ′Абдуллах ибн Бурейда, Матар (аль-Уаррак) передал мне послание: \"Возьми бумагу и чернильницу, и приходи\". Я взял бумагу и чернильницу, и мы пришли к нему, и он рассказывал: \"Мне рассказал мой отец, нам рассказал ′Абдуллах ибн Мугаффаль\". Затем, когда прибыл Яхья ибн Аби Касир, Матар (аль-Уаррак) передал мне послание: \"Возьми бумагу и чернильницу, и приходи\". Я взял бумагу и чернильницу, и мы пришли к нему. Тогда (Яхья) вытащил перед нами книгу Абу Салляма. Мы спросили: \"Ты слышал эти (хадисы) от Абу Салляма?!\". Он ответил: \"Нет!\". Мы спросили: \"Значит, от того, кто слышал от Абу Салляма?!\". Он ответил: \"Нет!\". Тогда мы сказали: \"Ты рассказываешь такие хадисы, который ты не слышал от этого человека и не слышал их от того, кто слышал их от него?!\"». </i>Таков смысл этой истории. Её от меня записал Муслим ибн уль-Хаджжадж."],["p","ГЛАВА 48: УПОМИНАНИЕ СООБЩЕНИЙ, ПЕРЕДАННЫХ ОТ ′АИШИ (ДА БУДЕТ ДОВОЛЕН ЕЮ АЛЛАХ), ГДЕ ОНА ОТРИЦАЕТ ТО, ЧТО ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ПРИ ЖИЗНИ ВИДЕЛ АЛЛАХА"],["p","Представители нашей общины из числа сподвижников и их последователей, а также тех, кто пришёл после них, вплоть до тех учёных, которых мы застали в наши дни, не разногласили и не сомневались в том, что все верующие воочию увидят своего Творца в День Воскресения. Учёные разногласили лишь в том, видел ли пророк (да благословит его Аллах и приветствует) своего Всемогущего и Великого Творца при своей жизни. Таким образом, между ними не было разногласий относительно того, что верующие увидят своего Творца в День Воскресения. Поймите же, что это два разных вопроса, и не ошибайтесь, а не то вы сойдёте с прямого пути."]],[["p","482 ― Масру́к рассказывал: <i>«Однажды, когда я находился у 'Аиши и полулежал, опираясь на локоть, она сказала:</i> \"<i>О Абу 'Аиша</i><sup class=\"fn\">620</sup><i>! Великую ложь возводит на Аллаха тот, кто говорит одно из трёх\". Я спросил: \"Что же именно?\". Она сказала: \"Великой ложью, возводимой на Аллаха, являются слова того, кто утверждает, будто Мухаммад видел своего Господа\". Я полулежал, (но, услышав её слова), сел и сказал: «О мать верующих! Погоди и не торопи меня. Разве Аллах не сказал:</i> <b>\"Он видел его на ясном горизонте\"</b><sup class=\"fn\">621</sup>, <i>и: </i><b>\"Он уже видел его другое нисхождение\"</b><sup class=\"fn\">622</sup><i>?!». 'Аиша сказала: «Я была первой из членов этой общины, кто спросил об этом посланника Аллаха (да благословит его Аллах и приветствует), на что он сказал:</i> <b><i>\"Это — Джибриль, и я видел его в том образе, в каком он был создан, только в этих двух случаях</i></b><sup class=\"fn\">623</sup><b><i>. Я видел, как (Джибриль) спускался с небес, и был он столь велик, что тело его закрывало всё пространство между небом и землёй\". </i></b>"],["n",[[620,"Абу 'Аиша (отец 'Аиши) — кунья Масрука."],[621,"Сура «ат-Такуир», аят 23."],[622,"Сура «ан-Наджм», аят 13."],[623,"Имеются в виду случаи, о которых упоминается в двух приводимых выше аятах."]]],["p","<i>('Аиша также) сказала: «Разве ты не слышал, что Аллах говорит: </i><b>\"Взоры не могут постичь Его, а Он постигает взоры. Он - Проницательный (или Добрый), Сведущий\"</b><sup class=\"fn\">624</sup><i>?! И разве ты не слышал, что Аллах говорит:</i> <b>\"Человек не достоин того, чтобы Аллах разговаривал с ним иначе, как посредством откровения или через завесу. Или же Он отправляет посланца, который с Его позволения внушает посредством откровения то, что Он желает. Воистину, Он - Возвышенный, Мудрый\"</b><sup class=\"fn\">625</sup><i>?!».</i>"],["n",[[624,"Сура «аль-Ан′ам», аят 103."],[625,"Сура «аш-Шура», аят 51."]]],["p","<i>Затем она сказала: «И великой ложью, возводимой на Аллаха, являются слова того, кто утверждает, будто посланник Аллаха (да благословит его Аллах и приветствует) утаил что-то из Книги Аллаха. Всевышний Аллах говорит: </i><b>\"О посланник! Возвести то, что ниспослано тебе от своего Господа. Если ты не сделаешь этого, то не донесешь Его послания. Аллах защитит тебя от людей\"</b><sup class=\"fn\">626</sup>. <i>И великой ложью, возводимой на Аллаха, являются слова того, кто утверждает, будто (пророк, да благословит его Аллах и приветствует), сообщал о том, что будет завтра. Всевышний Аллах говорит: </i><b>«Скажи: \"Никто из тех, кто на небесах и на земле, не ведает сокровенное, кроме Аллаха\"»</b><sup class=\"fn\">627</sup>»<sup class=\"fn\">628</sup>."],["n",[[626,"Сура «аль-Маида», аят 67."],[627,"Сура «ан-Намль», аят 65."],[628,"Муслим, 177; Абу Я’ля, 4901; Ибн Манда в «аль-Иман», 765 и др."]]],["p","483 ― [Под этим номером приведено то же самое сообщение, что и под № 482]."],["p","484 ― В другой версии пришло, что ‘Аиша (да будет доволен ею Аллах) сказала: <i>«Если бы Мухаммад (да благословит его Аллах и приветствует) скрыл хоть что-то из того, что ему ниспослал Аллах, он скрыл бы этот аят</i><sup class=\"fn\">629</sup><i>: </i><b>«Вот ты сказал тому, кому Аллах оказал милость и кому ты сам оказал милость: \"Удержи свою жену при себе и побойся Аллаха\"»</b><sup class=\"fn\">630</sup>."],["n",[[629,"Так как в этом аяте содержится упрёк в его адрес, но он не стал скрывать даже это."],[630,"Сура «аль-Ахзаб», аят 37. Эту версию передали Муслим, 177; Ибн Джарир, 11/512; ан-Насаи в «ас-Сунан аль-кубра», 11408."]]]],[["p","485 ― [Под этим номером приведено то же самое сообщение, что и под № 484]."],["p","486 ― ′А́мир аш-Ша′би передал, что Масру́к ибн аль-Аджда′ слышал, как ′Аиша (да будет доволен ею Аллах) говорила: <i>«Тот, кто сказал что-то из этих трёх, возвёл на Аллаха великую ложь. Речь идёт о том, кто сказал, что Мухаммад (да благословит его Аллах и приветствует) видел своего Господа, и что Мухаммад (да благословит его Аллах и приветствует) скрыл что-то из Откровения, и что Мухаммад (да благословит его Аллах и приветствует) знал, что будет завтра». </i>"],["p","Масрук спросил: <i>«О мать верующих! Разве он не видел Его?!». </i>Она ответила: <i>«Нет! Он видел Джибриля. Он видел его дважды в его истинном облике: один раз на высшем горизонте, а другой раз тот закрыл собой небесный горизонт»</i><sup class=\"fn\">631</sup>."],["n",[[631,"Ибн Хиббан в «Сахихе», 60."]]],["p","487 ― [Под этим номером приведено то же самое сообщение, что и под № 482. Немного отличается лишь конец сообщения, поэтому мы упомянем только его]."],["p","′Аиша (да будет доволен ею Аллах) сказала: <i>«Я спросила посланника Аллаха (да благословит его Аллах и приветствует) об этих (аятах), на что он сказал: </i><b><i>\"Я видел Джибриля, который снизошёл к горизонту в своём (истинном) облике и закрыл собой весь горизонт\"</i></b><i>»</i><sup class=\"fn\">632</sup>."],["n",[[632,"Ан-Насаи в «ас-Сунан аль-кубра», 11147."]]],["p","Я считаю, что ′Аиша (да будет доволен ею Аллах) произнесла эти слова<sup class=\"fn\">633</sup> в состоянии гнева. Лучше было бы произнести более прекрасные слова, которые передали бы то, что она желала высказать. Но не совсем хорошо, когда мужчина или женщина говорят, что Ибн ‘Аббас, Абу Зарр, Анас ибн Малик и ещё многие другие люди возвели великий навет на своего Господа. Однако во время гнева человек иногда произносит какие-то слова, которые следовало бы заменить более хорошими и прекрасными словами."],["n",[[633,"Имеются в виду слова: «Великую ложь возводит на Аллаха тот, кто говорит одно из трёх»."]]],["p","Но максимум, что из этого вытекает, это то, что ′Аиша (да будет доволен ею Аллах), Абу Зарр (да будет доволен им Аллах), Ибн ′Аббас (да будет доволен Аллах им и его отцом) и Анас ибн Малик (да будет доволен им Аллах) разногласили в том, видел ли пророк (да благословит его Аллах и приветствует) своего Господа. ′Аиша (да будет доволен ею Аллах) сказала, что пророк (да благословит его Аллах и приветствует) не видел своего Господа. А Абу Зарр (да будет доволен им Аллах) и Ибн ′Аббас (да будет доволен Аллах им и его отцом) сказали, что пророк (да благословит его Аллах и приветствует) видел своего Господа."],["p","В разных наших книгах я уже говорили о том, что отрицание не указывает обязательно на наличие знания, а вот утверждение указывает на наличие знания. ′Аиша (да будет доволен ею Аллах) не передала от пророка (да благословит его Аллах и приветствует), что он сообщил ей, что не видел своего Всемогущего и Великого Господа. Она всего лишь прочитала слова Всемогущего и Великого Аллаха: <b>«Взоры не могут постичь Его…», </b>а также: <b>«Человек не достоин того, чтобы Аллах разговаривал с ним иначе, как посредством откровения…». </b>Если человек поразмыслит над этими двумя аятами и если ему будет оказано содействие в понимании истины, он поймёт, что ни в одном из этих аятов нет указаний на правоту того, кто обвиняет в возведении лжи на Аллаха тех, кто говорит, что Мухаммад (да благословит его Аллах и приветствует) видел своего Господа. А что же сказать о том, кто говорит о таких, что они возвели величайший навет на Аллаха. Ведь слова Аллаха: <b>«Взоры не могут постичь Его…» </b>могут иметь два смысла, если опираться на мнение тех, кто утверждает видение пророком (да благословит его Аллах и приветствует) своего Всемогущего и Великого Творца."]],[["p","488 ― Возможно, слова Аллаха: <b>«Взоры не могут постичь Его…» </b>означают то, что сказал Ибн ‘Аббас своему вольноотпущеннику ′Икриме: <i>«Речь идёт о Его свете. Когда Он показывается с (завесой) Своего света, ничто не может постичь Его»</i><sup class=\"fn\">634</sup>."],["n",[[634,"См. сообщение № 419."]]],["p","А второе возможное толкование таково: Его не могут постичь взоры людей. Так как более очевидно из арабского языка, что слово «абсар» (взоры) указывает на взоры группы людей. Я не думаю, что хоть какой-нибудь араб, опираясь на арабский язык, скажет, что слово «абсар» (взоры) можно использовать, когда речь идёт о взоре (или зрении) одного человека. Когда речь идёт о взоре (или зрении) одного человека, говорят «басар» (взор). Мы не слышали, чтобы кто-нибудь из арабов говорил о взоре одного человека даже в двойственном числе, не говоря уже о множественном."],["p","Поэтому если мы скажем, что взоры людей видели нашего Господа в этом мире, то мы выскажем ложное мнение и клевету. Но совсем другое дело, если человек говорит, что Мухаммад (да благословит его Аллах и приветствует) видел своего Господа, и он единственный, кто видел его, среди всех творений. То есть этот человек не говорит, что взоры видели их Господа в этом мире. О обладатели разума! Скажите мне, если человек говорит, что пророк (да благословит его Аллах и приветствует) видел своего Господа, и он единственный, кто видел его, среди всех творений, то разве он этим утверждает, что взоры видели их Господа в этом мире?! О обладатели разума! Поймите это замечание и тогда вы поймёте, что Ибн ‘Аббас, Абу Зарр, Анас ибн Малик (да будет доволен ими Аллах) и те, кто согласился с ними, не возводили на Аллаха великий навет и не противоречили даже букве из Книги Аллаха в этом вопросе."],["p","Что же касается упомянутого ею аята: <b>«Человек не достоин того, чтобы Аллах разговаривал с ним иначе, как посредством откровения или через завесу», </b>то ни Абу Зарр, ни Ибн ‘Аббас, ни Анас ибн Малик, ни кто-то другой из утверждающих видение пророком (да благословит его Аллах и приветствует) своего Творца, не говорили, что Аллах говорил с ним в то время, когда он видел своего Господа. Тот, кто сказал, что пророк (да благословит его Аллах и приветствует) видел своего Господа, не противоречил словам Всевышнего Аллаха: <b>«Человек не достоин того, чтобы Аллах разговаривал с ним иначе, как посредством откровения или через завесу». </b>Этому аяту противоречит лишь тот, кто скажет, что пророк (да благословит его Аллах и приветствует) видел своего Господа, и Аллах говорил с ним в этот момент."],["p","Ибн ′Умар, который был великим учёным, обладал набожностью и пониманием религии, занимал высокое место в исламе и в знаниях, искал знание этого вопроса у великого толкователя Корана, двоюродного брата пророка (да благословит его Аллах и приветствует)<sup class=\"fn\">635</sup>. Он отправлял к нему людей с вопросом: видел ли пророк (да благословит его Аллах и приветствует) своего Господа?! Ведь он знал, что Ибн ‘Аббас знает этот вопрос, и поэтому хотел перенять от него это знание."],["n",[[635,"Имеется в виду ‘Абдуллах ибн ‘Аббас (да будет доволен Аллах им и его отцом). Его отец аль-‘Аббас (да будет доволен им Аллах) был дядей пророка (да благословит его Аллах и приветствует) со стороны отца."]]]],[["p","Достоверно передано, что Ибн ‘Аббас утверждал, что пророк (да благословит его Аллах и приветствует) видел своего Господа. Каждый учёный знает, что этот вопрос относится к числу таких, которые нельзя понять своим разумом, мнениями, сердцем или предположениями. Подобное знание можно перенять только из ниши пророчества, то есть из Корана или из слов избранного пророка (да благословит его Аллах и приветствует). Я не думаю, что кто-то из обладателей знания будет думать, что Ибн ‘Аббас сказал, что пророк (да благословит его Аллах и приветствует) видел своего Господа, только на основе своего мнения и предположения. То же самое никто не скажет ни про Абу Зарра, ни про Анаса ибн Малика."],["p","489 ― Мы скажем то же самое, что сказал Ма’мар ибн Ра́шид. Когда упомянули о разногласиях между ‘Аишей (да будет доволен ею Аллах) и Ибн ‘Аббасом (да будет доволен Аллах им и его отцом) в этом вопросе, Ма’мар ибн Ра́шид сказал: <i>«Мы не считаем ′Аишу более знающей, чем Ибн ′Аббас». </i>"],["p","Мы скажем: ‘Аиша – это правдивейшая, дочь правдивейшего, любимица того, кого любил Аллах, обладательница религиозного знания и понимания. Также и Ибн ′Аббас (да будет доволен Аллах им и его отцом) – двоюродный брат пророка (да благословит его Аллах и приветствует). Пророк (да благословит его Аллах и приветствует) обратился за него с мольбой, чтобы Аллах наделил его мудростью и знанием. И его также называли «тарджуман аль-Куран» (великий толкователь Корана). Даже сам аль-Фарук<sup class=\"fn\">636</sup> (да будет доволен им Аллах) спрашивал его о некоторых смыслах Корана и принимал его мнения, даже если противоречили ему те сподвижники, которые были старше него и раньше него начали сопровождать пророка (да благословит его Аллах и приветствует). И вот если случились разногласия между Ибн ′Аббасом и ′Аишей, то никак нельзя сказать, что Ибн ′Аббас возвёл великий навет на Аллаха, ибо он всего лишь утвердил то, что отрицала ′Аиша (да будет доволен ею Аллах). Учёные не говорят такое даже тогда, когда кто-то из ученых ошибся в толковании аята из Книги Аллаха или пошёл в противоречие одной или нескольким суннам пророка (да благословит его Аллах и приветствует) из-за того, что до него не дошли эти сунны. Разве можно говорить, что возвёл на Аллаха великий навет тот, кто утвердил что-то, что не отрицается ни Кораном, ни Сунной. Поймите же это и не ошибайтесь!"],["n",[[636,"То есть ‘Умар ибн аль-Хаттаб (да будет доволен им Аллах)."]]],["p","490 ― ′Абдуллах ибн аль-Харис рассказывал: <i>«Однажды Ибн ′Аббас находился в одном собрании с Ка′бом. Ибн ′Аббас сказал: \"Мы, потомки Хашима, говорим, что Мухаммад (да благословит его Аллах и приветствует) видел своего Господа дважды\". Услышав это, Ка′б стал говорить: \"Превелик Аллах!\" так, что в горах раздалось эхо. Затем он сказал: \"Поистине, Аллах распределил Его видение и разговор с Ним между Мухаммадом и Мусой (мир им и благословение Аллаха). Мухаммад (да благословит его Аллах и приветствует) видел Его своим сердцем, а Муса говорил с ним\"»</i><sup class=\"fn\">637</sup><i>.</i>"],["n",[[637,"Ат-Тирмизи, 3278. Также см. сообщение № 439."]]]],[["p","Муджа́лид также передал со слов аш-Ша’би, который передавал со слов Масру́ка, что однажды он сказал ‘Аише (да будет доволен ею Аллах): <i>«О мать! Видел ли когда-нибудь Мухаммад (да благословит его Аллах и приветствует) своего Господа?». </i>Она ответила: <i>«Ты произнёс такие слова, от которых у меня встали волосы дыбом!». </i>Масру́к сказал: <i>«Подожди!».</i>"],["p","Масру́к рассказывал: <i>«После этого я прочитал ей: </i><b>\"Клянусь звездой, когда она падает\" </b><i>и до слов: </i><b>\"Он находился от него на расстоянии двух луков или даже ближе\"</b><sup class=\"fn\">638</sup>. <i>Она сказала: \"Ты ушёл не туда! Он (пророк) видел Джибриля в его истинном облике. Если кто-либо рассказывает тебе, что Мухаммад видел своего Господа, то он лжёт. И если кто-либо рассказывает тебе, что (Мухаммад) знает пять сокровенных вещей, то он лжёт. (Аллах сказал): </i><b>\"Воистину, только Аллах обладает знанием о Часе\"</b><sup class=\"fn\">639</sup><i>».</i>"],["n",[[638,"Сура «ан-Наджм», аяты 1-9."],[639,"Аллах сказал: <b>«Воистину, только Аллах обладает знанием о Часе, ниспосылает дождь и знает о том, что в утробах. Ни один человек не знает, что он приобретет завтра, и ни один человек не знает, в какой земле он умрет. Воистину, Аллах - Знающий, Ведающий». </b>(Сура «Лукман», аят 34)."]]],["p","491 ― ′Абд ур-Раззак рассказывал: <i>«Я рассказывал этот хадис Ма′мару, и он сказал: \"Мы не считаем ′Аишу более знающей, чем Ибн ′Аббас\"».</i>"],["p","Если я бы считал дозволенным аргументировать такими передатчиками, как Муджалид<sup class=\"fn\">640</sup>, я бы сказал, что все представители рода бану Хашим противоречили ‘Аише (да будет доволен ею Аллах) в этом вопросе, и все они утверждали, что пророк (да благословит его Аллах и приветствует) видел своего Господа дважды. И если взять мнение тех, кто разрешал аргументировать сообщениями таких, как Муджалид, то единогласное мнение членов рода бану Хашим предпочтительнее, чем слова одной ′Аиши, в котором её не поддержал ни один сподвижник, ни одна из жён пророка (да благословит его Аллах и приветствует) и ни одна из последовательниц сподвижников. Я ещё давно говорил: даже если бы ′Аиша (да будет доволен ею Аллах) передала от пророка (да благословит его Аллах и приветствует) свои убеждения в этом вопросе, передала бы от него, что он не видел своего Великого и Возвышенного Господа, и сказала бы, что пророк (да благословит его Аллах и приветствует) сам сказал ей об этом, и в то же время Ибн ′Аббас, Анас ибн Малик и Абу Зарр (да будет доволен ими Аллах) передали бы от пророка (да благословит его Аллах и приветствует), что он видел своего Господа, то каждый учёный, разбирающийся в хадисоведении, сказал бы, что со стороны знания и фикха мы обязаны принять слово тех, кто передаёт, что пророк (да благословит его Аллах и приветствует) видел своего Господа."],["n",[[640,"Муджалид ибн Са’ид был слабым передатчиком. Сообщение, которое приведено под № 490, передано именно от него."]]],["h2","ГЛАВА 49: УТВЕРЖДЕНИЕ СМЕХА НАШЕГО ВСЕМОГУЩЕГО И ВЕЛИКОГО ГОСПОДА БЕЗ ОПИСАНИЯ ОБРАЗА ЕГО СМЕХА"]],[["p","Его смех не подобен смеху творений, а смех творений не подобен Его смеху. Мы веруем в то, что Он смеётся, как об этом сообщил пророк (да благословит его Аллах и приветствует), но мы ничего не говорим об образе Его смеха, велик Он и возвышен. Только Всемогущий и Великий Аллах знает, каков образ Его смеха, и Он не сообщил нам об этом. Мы лишь говорим то, что сказал пророк (да благословит его Аллах и приветствует), уверовав в это нашими сердцами. И мы не говорим о том, что он не разъяснил нам, и знание о чём принадлежит только Всевышнему Аллаху."],["p","492 ― Анас ибн Малик (да будет доволен им Аллах) передал со слов ′Абдуллаха ибн Мас′уда (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Последним из тех, кто войдёт в Рай, станет человек, который будет то идти по Мосту (сыра́т), то падать ничком», </i></b>и затем он упомянул длинный хадис. И в конце хадиса сказано: <b><i>«Наш Всеблагой и Всевышний Господь скажет: \"О Мой Раб! Что ещё для тебя сделать, чтобы ты перестал обращаться ко Мне с просьбами? Останешься ли ты довольным, если Я дарую тебе весь ближний мир и ещё один, подобный ему?\". А он скажет: \"Неужели Ты насмехаешься надо мной, ведь Ты – Господь величия?!\"». </i></b>"],["p","Анас ибн Малик сказал: <i>«И тут ′Абдуллах (ибн Мас′уд) засмеялся так, что показались его зубы. Затем он сказал: \"Не спросите ли вы, что заставляет меня смеяться?\". (Люди) спросили: \"Почему ты смеёшься?\". Он ответил: «Потому что (при этих словах) засмеялся посланник Аллаха (да благословит его Аллах и приветствует), а затем он сказал нам: </i><b><i>\"Не спросите ли вы, что заставляет меня смеяться?\"</i></b><i>. (Люди) спросили: \"Почему ты смеёшься, о посланник Аллаха?!\". Он ответил: </i><b><i>«Потому что, когда (человек) спросит: \"Неужели Ты насмехаешься надо мной, ведь Ты – Господь величия?!\" — Всеблагой и Всевышний Господь засмеётся»</i></b><sup class=\"fn\">641</sup>."],["n",[[641,"Муслим, 187; Ахмад, 1/391, 410; Ибн Хиббан, 7430; Абу Я′ля, 4980, 5290; Ибн Манда в «аль-Иман», 841; аль-Аджурри в «аш-Шари′а», 690; Ибн Аби ′Асым в «аль-Ахад аль-масани», 248; ат-Табарани в «аль-Кабир», 9775."]]],["p","493 ― Са′ид ибн уль-Мусеййяб и ′Ата ибн Язид аль-Лейси передали, что Абу Хурейра (да будет доволен им Аллах) сообщил им, что однажды люди спросили пророка (да благословит его Аллах и приветствует): <i>«Увидим ли мы нашего Господа в День Воскресения?!», </i>и далее упомянут длинный хадис. В нём пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«И останется меж Раем и Адом лишь один человек, и он войдёт в Рай последним. Лицо его будет обращено в сторону Огня, и он скажет: \"О Господь мой! Отврати моё лицо от Огня, ибо ветер его отравил и погубил меня, а пламя его сожгло меня!\". Всемогущий и Великий Аллах скажет: \"А если Я сделаю это для тебя, попросишь ли ты чего-нибудь ещё?\". Он скажет: \"Нет, клянусь Твоим величием!\" – и станет клясться в этом своему Господу, давая обещания, какие Тому будет угодно. Тогда Аллах отвратит его лицо от Огня». </i></b>"]],[["p","Затем пришла ещё часть хадиса, после чего он сказал: <b><i>«(Аллах) скажет: \"Разве ты не давал клятв и обещаний не просить ничего, кроме того, что было тебе даровано?\". Он ответит: \"О Господь мой! Не делай меня несчастнейшим из Твоих созданий!\", и тогда Всемогущий и Великий Аллах посмеется над его (словами)», </i></b>и затем приходит оставшаяся часть хадиса<sup class=\"fn\">642</sup>."],["n",[[642,"Аль-Бухари, 6573; Муслим, 182."]]],["p","494 ― Также этот хадис рассказал нам Мухаммад ибн Яхья, которому рассказал ′Абд ур-Раззак, а ему сообщил Ма′мар от аз-Зухри, а тот – от ′Ата ибн Язида аль-Лейси, который передавал от Абу Хурейры (да будет доволен им Аллах)."],["p","495 ― Также этот хадис рассказал нам Мухаммад, которому рассказал Сулейман ибн Дауд аль-Хашими, а ему рассказал Ибрахим ибн Са′д от ибн Шихаба (аз-Зухри), который передавал от ′Ата ибн Язида, а тот – от Абу Хурейры (да будет доволен им Аллах)."],["p","Этот хадис передали вместе Абу Хурейра (да будет доволен им Аллах) и Абу Са′ид (да будет доволен им Аллах), потому что в хадисе пришло, что Абу Са′ид сказал Абу Хурейре: <i>«Я свидетельствую, что пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>«Аллах скажет: \"Это тебе, и ещё в десять раз больше\"». </i></b>"],["p","Эти слова указывают на то, что Абу Са′ид (да будет доволен им Аллах) запомнил этот хадис от пророка (да благословит его Аллах и приветствует) в том виде, в каком его передавал Абу Хурейра (да будет доволен им Аллах), а ещё он запомнил эту добавку: <b><i>«Аллах скажет: \"Это тебе, и ещё в десять раз больше\"». </i></b>А Абу Хурейра (да будет доволен им Аллах) запомнил только такую фразу: <b><i>«Это тебе, и ещё столько же». </i></b>Но фраза, которую упомянул Абу Хурейра (да будет доволен им Аллах), не противоречит тому, что упомянул Абу Са′ид (да будет доволен им Аллах)<sup class=\"fn\">643</sup>."],["n",[[643,"Затем имам Ибн Хузейма (да помилует его Аллах) указал на то, что сторонники новшеств и заблуждений критикуют этот хадис и заявляют о его слабости, и разъяснил, что хадис не является слабым, опровергнув их аргументы. Его разъяснение касается в основном арабского языка и не сильно связано с нашей темой. Нам достаточно того, что этот хадис передали аль-Бухари и Муслим, и никто из учёных не называл его слабым. А Аллах знает лучше!"]]],["p","496 ― Абу Хурейра (да будет доволен им Аллах) также передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Всемогущий и Великий Аллах засмеётся двум мужам, один из которых (сначала) убьёт другого, (а потом) оба они войдут в Рай. Первый (будет) сражаться на пути Аллаха и станет мучеником, а затем его убийца раскается пред Аллахом, примет ислам, станет сражаться на пути Аллаха и станет мучеником»</i></b><sup class=\"fn\">644</sup>."],["n",[[644,"Муслим, 1890; ан-Насаи, 6/38; Ибн Маджа, 191; Ахмад, 2/244, 464; ′Абдуллах ибн Ахмад в «ас-Сунна», 1137, 1138; аль-Хумейди, 1122; аль-Аджурри в «аш-Шари′а», 674. Сказал Кывам ус-Сунна аль-Асбахани (да помилует его Аллах): <i>«Некоторые люди отвергли атрибут (Аллаха) смех, но достоверно пришло, что пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Аллах засмеётся двум мужам, один из которых убьёт другого\". </i></b><i>А если хадис достоверный, то мусульманину запрещено его отвергать. А если кто-то отвергает его, то есть опасность неверия для него.</i> <i>Некоторые учёные сказали, что тот, кто отверг смех (Аллаха), является глубоким невеждой. А ещё кто-то отнёс этот хадис к слабости и сказал: \"Но даже если бы он был крепким, всё равно нужно было бы его отвергнуть\". Это – страшные слова, когда человек отвергает высказывания посланника Аллаха (да благословит его Аллах и приветствует). </i> <i>Истина же состоит в том, что если хадис достоверен от пророка (да благословит его Аллах и приветствует), мы обязаны уверовать в него, но не описывать образ этого (атрибута). Однако мы утверждаем атрибут и веруем в него». </i>См. «аль-Худжжа фи баян аль-махаджжа», 2/528."]]]],[["p","497 ― [Под этим номером приведено то же самое сообщение, что и под № 496]<sup class=\"fn\">645</sup>."],["n",[[645,"Здесь автор привёл тот же самый хадис только по другой цепочке передатчиков. По данной цепочке этот хадис передали Малик в «Муватта», 2/460; аль-Бухари, 2826; ан-Насаи, 6/38; Ибн Хиббан, 215, 4667; аль-Аджурри в «аш-Шари′а», 672, 673, 675, 676; аль-Лялякаи в «И′тикад ахли ссунна», 723; Ибн Батта в «аль-Ибана», 69."]]],["p","498 ― [Под этим номером приведено то же самое сообщение, что и под № 496]<sup class=\"fn\">646</sup>."],["n",[[646,"Здесь автор привёл тот же самый хадис только по другой цепочке передатчиков. По данной цепочке этот хадис передал Ибн Хиббан, 4666."]]],["p","499 ― [Под этим номером приведено то же самое сообщение, что и под № 496]."],["p","500 ― В другой версии пришло, что Абу Хурейра (да будет доволен им Аллах) рассказывал: <i>«Однажды посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Аллах засмеётся двум мужам, один из которых убил другого, но они оба войдут в Рай\". </i></b><i>Люди спросили: \"Как это, о посланник Аллаха?!\". Он сказал: </i><b><i>\"(Первый) будет убит и войдёт в Рай, а затем Аллах примет покаяние другого и приведёт его к исламу, после чего он станет сражаться на пути Аллаха и падёт мучеником\"</i></b><i>»</i><sup class=\"fn\">647</sup>."],["n",[[647,"Муслим, 1890; Ахмад, 2/318; ′Абд ур-Раззак в «Мусаннафе», 20280; аль-Аджурри в «аш-Шари′а», 677."]]],["p","501 ― [Под этим номером приведено то же самое сообщение, что и под № 500]."],["p","502 ― Анас ибн Малик (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Всеблагой и Всевышний (Аллах) удивится (или: засмеётся) двум мужам, один из которых убил другого, но они оба войдут в Рай. Один из них убьёт другого и тот (умерший) войдёт в Рай, после чего Аллах примет покаяние другого и приведёт его к исламу»</i></b><sup class=\"fn\">648</sup>."],["n",[[648,"Данная версия передана по очень слабой цепочке передатчиков. А Аллах знает лучше!"]]],["p","503 ― ′Ата ибн Ясар передал, что ′Аиша (да будет доволен ею Аллах) рассказывала: <i>«Однажды посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Поистине, Всемогущий и Великий Аллах смеётся над отчаянием рабов, когда облегчение уже близко\". </i></b><i>Я спросила: \"О посланник Аллаха, пусть мои отец и мать станут выкупом за тебя! Разве наш Господь смеётся?!\". Он ответил: </i><b><i>\"Да! Клянусь Тем, в Чьей руке моя душа! Поистине, Он смеётся\"</i></b><i>. Тогда я сказала: \"Значит, мы не лишимся добра от Него, раз Он смеётся!\"»</i><sup class=\"fn\">649</sup>."],["n",[[649,"Данная версия передана по очень слабой цепочке передатчиков. А Аллах знает лучше! При этом данный хадис пришел со слов Абу Разина аль-′Укейли (да будет доволен им Аллах). Его передали Ахмад, 4/11; Ибн Маджа, 181; ат-Таялиси, 1/147; ′Абдуллах ибн Ахмад в «ас-Сунна», 491, 492; аль-Аджурри в «аш-Шари′а», 681, 682."]]]],[["p","504 ― Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Когда Аллах соберёт в День Воскресения первых и последних, Всеблагой и Всевышний Господь придёт к верующим и остановится над ними, а верующие будут стоять на возвышенном месте. Он скажет: \"Узнаете ли вы вашего Господа?!\". Они ответят: \"Если Он придёт к нам (в известном нам образе), мы узнаем Его\". А затем Он засмеётся в их лица, и они падут ниц»</i></b><sup class=\"fn\">650</sup>."],["n",[[650,"Ибн Аби ′Асым в «ас-Сунна», 631, и др. Также этот хадис пришёл со слов Джабира (да будет доволен им Аллах). В его версии сказано: <b><i>«(Аллах) скажет: \"Я – ваш Господь\". Они скажут: \"Мы (хотим) взглянуть на Тебя\". Тогда Всеблагой и Всевышний (Аллах) покажется им смеющимся». </i></b>Эту версию передали Муслим, 191; Ахмад, 3/383, и др."]]],["p","505 ― Абу Муса (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«В День Воскресения наш Всемогущий и Великий Господь покажется нам смеющимся»</i></b><sup class=\"fn\">651</sup>."],["n",[[651,"′Абдуллах ибн Ахмад в «ас-Сунна», 503; аль-Аджурри в «аш-Шари′а», 683; ад-Даракутни в «ас-Сыфат», 34; Ибн Батта в «аль-Ибана», 68."]]],["p","506 ― В другой версии со слов Абу Мусы (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«В День Воскресения Аллах соберёт (все) общины в одном месте», </i></b>затем он упомянул некоторые события Судного Дня. После чего он сказал: <b><i>«Наш Господь покажется им смеющимся и скажет: \"Радуйтесь, о мусульмане! Нет среди вас ни одного, кроме как Я обязательно поместил на его место в Аду иудея или христианина\"»</i></b><sup class=\"fn\">652</sup>."],["n",[[652,"Ахмад, 19654; ′Абд ибн Хумейд, 540; аль-Аджурри в «аш-Шари′а», 684, и др."]]],["p","507 ― ′Али ибн Раби′а рассказывал: <i>«Однажды ′Али (да будет доволен им Аллах) посадил меня позади себя (на верховом животном), а затем вышел за пределы Куфы, поднял взор к небу и сказал: \"Нет истинного бога, кроме Тебя! Пречист Ты! Поистине, я был из числа несправедливых! Прости же мне!\". Затем он посмотрел на меня, засмеялся и сказал: \"Не спросишь меня, из-за чего я смеюсь?!\". Я сказал: \"Из-за чего ты смеёшься, о правитель верующих?!\". Тогда он сказал: «Однажды посланник Аллаха (да благословит его Аллах и приветствует) посадил меня позади себя (на верховом животном), а затем вышел к лавовым полям Медины, поднял голову к небу и сказал: </i><b><i>\"Нет истинного бога, кроме Тебя! Пречист Ты! Поистине, я был из числа несправедливых! Прости же мне!\". </i></b><i>Затем он посмотрел на меня, засмеялся и сказал: </i><b><i>\"Не спросишь меня, из-за чего я смеюсь?!\"</i></b><i>. Я сказал: \"Из-за чего ты смеёшься, о посланник Аллаха?\". Он ответил: </i><b><i>\"Я смеюсь из-за смеха моего Господа и из-за того, что Он удивляется Своему рабу, который знает, что никто не прощает грехи, кроме Него!\"</i></b><i>»</i><sup class=\"fn\">653</sup>."],["n",[[653,"Ибн Аби Шейба в «Мусаннафе», 29401; аль-Аджурри в «аш-Шари′а», 685, 686; Ибн Батта в «аль-Ибана», 74, 75; ат-Табарани в «ад-Ду’а», 777, 778, 779; аль-Хаким в «аль-Мустадрак», 2482. Также этот хадис по другой цепочке передатчиков передали ат-Тирмизи, 3446; Абу Дауд, 2602; Ахмад, 1/97; Ибн Хиббан, 2698; ат-Таялиси, 132; Абу Я′ля, 586; ′Абд ибн Хумейд, 89; ан-Насаи в «аль-Кубра», 8799, 10336; ат-Табарани в «ад-Ду’а», 781, 787; аль-Аджурри в «аш-Шари′а», 687, 688."]]]],[["p","508 ― Исхак ибн Ра́шид передал, что женщина из числа ансаров, которую звали Асма бинт Язид ибн ас-Сакан, рассказывала: <i>«Когда умер Са′д ибн Му′аз, его мать закричала, а посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Перестань плакать и печалиться! Воистину, твой сын – первый, кому засмеялся Аллах, и из-за него сотрясся трон (′арш)\"</i></b><i>»</i><sup class=\"fn\">654</sup>."],["n",[[654,"Ахмад, 6/456; ′Абдуллах ибн Ахмад в «ас-Сунна», 1142; Ибн Аби Шейба в «Мусаннафе», 32318; Ибн Аби ′Асым в «ас-Сунна», 559; Ибн Са′д в «ат-Табакат», 3/434; аль-Хаким в «аль-Мустадрак», 4925; ат-Табарани в «аль-Кабир», 6/12, 24/185; Ибн Батта в «аль-Ибана», 77. Цепочка передатчиков является слабой. А Аллах знает лучше!"]]],["p","509 ― Абу Фира́с передал, что ′Абдуллах ибн ′Амр (да будет доволен Аллах им и его отцом) сказал: <i>«Аллах трижды смеётся тому, кто выходит в море: когда он садится (на судно) и оставляет свою семью и своё имущество, когда он испытывает головокружение, и когда он видит сушу. (И в этот момент человек может оказаться) либо благодарным, либо неблагодарным»</i><sup class=\"fn\">655</sup><i>. </i>"],["n",[[655,"Ибн Аби Шейба в «Мусаннафе», 19490; Ибн Батта в «аль-Ибана», 79, и др."]]],["p","Прежде я уже говорил о том, что учёные не разногласили относительно того, что верующие увидят своего Создателя в День Воскресения. Велик наш Господь и Могуч! И они не разногласили относительно того, что пророк (да благословит его Аллах и приветствует), который был лучшим из верующих, увидит своего Создателя в День Воскресения. Они разногласили лишь в том, видел ли пророк (да благословит его Аллах и приветствует) своего Всемогущего и Великого Господа перед тем, как к нему пришла смерть."],["p","510 ― Хубейра ибн Яри́м передал, что Ибн Мас′уд (да будет доволен им Аллах) сказал: <i>«Если кто-либо утверждает, что Аллаха можно увидеть открыто, то он впал в многобожие. И если кто-либо утверждает, что Муса попросил у своего Господа возможности увидеть Его открыто, то он впал в многобожие»</i><sup class=\"fn\">656</sup>."],["n",[[656,"Данное сообщение является выдуманным (мавду′). Среди его передатчиков Джабир ибн Саййяр ас-Сухейми, которого учёные критиковали. Дело в том, что он потерял свои книги и из-за этого стал очень сильно путаться в передаче хадисов. А от Ибн Мас′уда (да будет доволен им Аллах) по достоверным путям передачи пришло совсем другое, как это разъяснит ниже автор (да помилует его Аллах)."]]],["p","Этим преданием стал аргументировать джахмит, заявляя, что Всевышнего Аллаха невозможно увидеть, и что ни пророк (да благословит его Аллах и приветствует), ни верующие не увидят своего Господа в День Воскресения. Но это сообщения является лживым, выдуманным и ложным. Его выдумали некоторые джахмиты. Но у нас по милости Аллаха есть слова Ибн Мас′уда (да будет доволен им Аллах), которые пришли к нам по двум непрерывным путям передачи, и в них совершенно обратное тому, что в этом выдуманном сообщении."]],[["p","511 ― Масру́к передал, что Ибн Мас′уд (да будет доволен им Аллах) сказал: <i>«Аллах соберёт людей в День Воскресения и глашатай объявит: \"О люди! Не будете ли вы довольным вашим Господом, Который сотворил вас, придал вам облик и наделил вас уделом, если Он направит каждого человека к тому, чему тот поклонялся в ближней жизни?! Разве это не будет справедливостью от вашего Господа?!\". Люди ответят: \"Конечно, (будем довольны)!\". Тогда (голос) скажет: \"Пусть каждый из вас направится к тому, к чему он обращался в ближней жизни!\", после чего перед ними появятся образы того, чему они поклонялись в ближней жизни. Перед теми, кто поклонялся ′Исе, появится шайтан (в образе) ′Исы. Перед теми, кто поклонялся ′Узейру, появится шайтан (в образе) ′Узейра. И так перед ними появятся даже деревья, ветки и камни. При этом мусульмане продолжат стоять неподвижно, и им будет сказано: \"Что с вами?! Почему вы не идёте, как пошли (другие) люди?!\". Они ответят: \"Поистине, у нас есть Господь, Которого мы ещё не видели\". (Господь) спросит: \"А как вы узнаете вашего Господа, если увидите Его?!\". Они скажут: \"Между нами и Им есть признак, увидев который, мы узнаем Его\". Он спросит: \"Что это (за признак)?\", после чего обнажит голень</i><sup class=\"fn\">657</sup><i>, и всякий, кто обладал позвонками, падет ниц, а останутся (стоять) лишь люди, чьи спины будут подобны коровьим рогам». </i>"],["n",[[657,"Всевышний Аллах сказал: <b>«В Тот День, когда обнажится голень (Аллаха), они (творения) будут призваны пасть ниц, но (лицемеры) не смогут (сделать этого)».</b> (Сура «аль-Калям», аят 42). В версии, которую привёл аль-Мунзири в «ат-Таргыб уа ттархиб», сказано: <i>«(Аллах) спросит: \"Что это за знак?\". Они ответят: \"Он обнажит Свою голень!\", и тогда Аллах обнажит Свою голень».</i>"]]],["p","В этом сообщении пришло, что Ибн Мас′уд (да будет доволен им Аллах): <i>«Поистине, я слышал, как посланник Аллаха (да благословит его Аллах и приветствует) рассказывал этот хадис несколько раз, и каждый раз, когда он достигал этого места, он смеялся»</i><sup class=\"fn\">658</sup>."],["n",[[658,"Передали Ибн Наср аль-Маруази в «Та′зым кадр ас-салят», 278; ат-Табарани в «аль-Кабир», 9/357; аль-Хаким в «аль-Мустадрак», 4/589. Хадис достоверный. См. «Сахих ат-Таргыб», 3591."]]],["p","512 ― Абу аз-За′ра́ передал со слов ′Абдуллаха ибн Мас′уда (да будет доволен им Аллах) длинный хадис, в котором сказано: <i>«Затем Всемогущий и Великий Аллах предстанет пред творениями и скажет: \"Кому вы поклонялись?\"».</i> Затем он стал рассказывать хадис далее и среди прочего сказал: <i>«Останутся лишь мусульмане, и Он спросит: \"Кому вы поклонялись?\". Они ответят: \"Мы поклонялись Аллаху и ничего не придавали Ему в сотоварищи\". Он спросит: \"Узнаете ли вы вашего Господа?\". Они ответят: \"Пречист Он! Если Он покажется нам, мы узнаем Его\", и в этот момент Он обнажит голень, и каждый верующий мужчина и верующая женщина непременно падут ниц пред Аллахом»</i><sup class=\"fn\">659</sup><i>.</i>"],["n",[[659,"Ибн Аби Шейба в «Мусаннафе», 37637; Ибн Джарир в «Тафсире», 10/480."]]]],[["p","513 ― Также этот хадис рассказал нам аль-Бистами, которому рассказал Абу Ну′айм, а ему рассказал Суфьян."],["p","Эти два сообщения ясно дают понять, что Ибн Мас′уд (да будет доволен им Аллах) подтверждал, что мусульмане увидят своего Всемогущего и Великого Творца в День Воскресения, когда Он обнажит голень, и что верующие падут ниц пред Аллахом, когда увидят Его в тот момент. Разве он<sup class=\"fn\">660</sup> мог обвинить в неверии того, кто говорит то, что у него самого является истиной, правдой и справедливостью?! Даже если бы это сообщение от Ибн Мас′уда (да будет доволен им Аллах) было бы достоверным, то мы бы разъяснили его правильно, а не так, как разъясняет джахмит (да пребудут над ним проклятия Аллаха). Мы сказали бы: если кто-либо утверждает, что Аллаха можно увидеть открыто в этом мире, то он лжёт и возводит навет. Потому что если что-либо можно увидеть открыто, то это увидит каждый видящий, когда между ним и этим нет преграды. Например, народ Мусы попросил Мусу, чтобы он показал им Аллаха открыто<sup class=\"fn\">661</sup>. Что же касается Мусы, то о его просьбе сказано в Коране так: <b>«Он </b>[Муса]<b> сказал: \"Господи! Покажись мне, чтобы я взглянул на Тебя\". Он</b> [Аллах] <b>сказал: \"Ты не увидишь Меня\"»</b><sup class=\"fn\">662</sup>. Муса не сказал: «Покажись мне, чтобы я взглянул на Тебя открыто», потому что когда говорят: «Открытое видение» (джахратан), то имеется в виду то, что видит каждый, у кого есть зрение. Но Всемогущий и Великий Аллах скрыт за завесой от людей этого мира в этом мире. Никто в этом мире не увидит своего Господа открыто. А ещё раньше мы разъясняли смысл слов Аллаха: <b>«Взоры не могут постичь Его»</b><sup class=\"fn\">663</sup>. Мы говорили, что возможно такое, что пророк (да благословит его Аллах и приветствует) был выделен тем, что он видел своего Творца, когда был на седьмом небе. Но пророк (да благословит его Аллах и приветствует) не видел своего Господа, находясь в этом мире."],["n",[[660,"То есть Ибн Мас′уд (да будет доволен им Аллах)."],[661,"Всевышний Аллах сказал: <b>«Люди Писания просят тебя, чтобы ты низвел им писание с неба. Мусу они попросили о еще большем, когда сказали: \"Покажи нам Аллаха открыто\". Тогда молния поразила их за их несправедливость». </b>(Сура «ан-Ниса», аят 153)"],[662,"Сура «аль-А′раф», аят 143."],[663,"Сура «аль-Ан′ам», аят 103."]]],["p","Я уже говорил о том, что учёные не разногласили относительно того, что все верующие увидят своего Творца в Последней жизни в День Воскрешения, но не в этом мире. А те, которые отрицают видение верующими их Творца в День Воскрешения, они не являются верующими для верующих. Более того они по своему положению в этом мире хуже для учёных, чем иудеи, христиане и огнепоклонники."]],[["p","514 ― Сказал Ибн аль-Мубарак: <i>«Мы передаём слова иудеев и христиан, но не можем передать слова джахмитов»</i><sup class=\"fn\">664</sup><i>. </i>"],["n",[[664,"′Абдуллах ибн Ахмад в «ас-Сунна», 25, 244; аль-Аджурри в «аш-Шари′а», 620; Абу Са′ид ад-Дарими в «ар-Радд ′аля-ль джахмия», 24."]]],["p","515 ― Джарир ибн ′Абдуллах (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, вы воочию увидите Всемогущего и Великого Аллаха в День Воскресения»</i></b><sup class=\"fn\">665</sup>."],["n",[[665,"Аль-Бухари, 7435; аль-Бейхакы в «аль-И′тикад», стр. 129."]]],["h2","ГЛАВА 50: УПОМИНАНИЕ ГЛАВ О ЗАСТУПНИЧЕСТВЕ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","Речь идёт о том заступничестве (шафа′ат), которым он был выделен среди всех остальных пророков (благословения им от Аллаха). Он будет заступаться за свою общину. Также речь пойдёт о том, что одни члены общины будут заступаться за других, а именно за тех, кого погубили их грехи и они были введены в Огонь. За таких будут заступаться с просьбами вывести их из Огня после того, как они были наказаны в нём соразмерно своим грехам, которые Аллах не простил им по Своей милости и щедрости. Лишь у Аллаха мы просим защиты от Огня!"],["p","ГЛАВА 51: УПОМИНАНИЕ ЗАСТУПНИЧЕСТВА, КОТОРЫМ АЛЛАХ ВЫДЕЛИЛ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) СРЕДИ ВСЕХ ОСТАЛЬНЫХ ПРОРОКОВ И ВЕРУЮЩИХ"],["p","Это – первое заступничество, когда он будет заступаться за членов своей общины, чтобы Аллах избавил их от стояния в День Воскресения, где они будут собраны со всеми предыдущими поколениями. Солнце приблизится к ним и начнёт причинять им страдания. Их охватит такая тревога и печаль, какую они не смогут вынести. Это не то заступничество, когда пророк (да благословит его Аллах и приветствует) будет просить у Аллаха, чтобы Он вывел из Огня тех членов мусульманской общины, которых Он туда ввёл за то, что они совершали в ближней жизни грехи, которые Аллах не пожелал простить им по Своей милости и щедрости. Это второе заступничество произойдёт уже после. Также сюда относится то, что пришло в религиозных текстах относительно того, что пророк (да благословит его Аллах и приветствует) был выделен тем, что именно он посмотрит на Всемогущего и Великого Аллаха во время заступничества."],["p","516-518 ― Абу Хурейра (да будет доволен им Аллах) рассказывал: <i>«Однажды посланнику Аллаха (да благословит его Аллах и приветствует) принесли мясо. Затем ему подали переднюю ногу овцы, которую он любил, и пророк (да благословит его Аллах и приветствует) откусил кусочек, а потом сказал: </i><b><i>«В День Воскресения я стану главой всех людей. А знаете ли вы о причине этого?! Дело в том, что Аллах соберёт людей, первых и последних, на одной обширной равнине так, что глашатай сможет обратиться ко всем людям сразу, и всех их можно будет охватить взором. В этот День солнце приблизится к ним, и охватят их такие скорбь и печаль, что у них не хватит ни сил, ни терпения переносить это. Тогда люди станут говорить друг другу: \"Разве вы не видите, что вас постигло?! Не поискать ли вам того, кто заступится за вас перед вашим Господом?!\". Некоторые из них скажут другим: \"Вам следует пойти к вашему праотцу Адаму\". Они придут к Адаму и скажут ему: \"О Адам! Ты – отец людей. Аллах создал тебя Своей рукой и вдохнул в тебя дух от Него, и велел ангелам склониться перед тобой до земли, так заступись же за нас перед твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". Он ответит им: \"Поистине, мой Господь сегодня разгневался так, как не гневался Он никогда раньше и не будет гневаться уже никогда больше. И Он запретил мне вкушать с дерева, но я ослушался Его. Сам я, сам я (нуждаюсь в защите). Вы же ступайте к другому. Ступайте к Нуху\".</i></b>"]],[["p","<b><i>Они придут к Нуху и скажут: \"О Нух! Поистине, ты – первый из посланников к обитателям земли, и Аллах назвал тебя благодарным рабом. Заступись же за нас пред твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". Он скажет им: \"Поистине, мой Господь сегодня разгневался так, как не гневался Он никогда раньше и не будет гневаться уже никогда больше. (Аллах) даровал мне только одну мольбу, и я уже обратился с ней против своего народа</i></b><sup class=\"fn\">666</sup>.<b><i> Ступайте к другому. Ступайте к Ибрахиму\".</i></b>"],["n",[[666,"Имеются в виду слова Нуха (мир ему): <b>«Господи! Не оставь на земле ни одного неверующего жителя!». </b>(Сура «Нух», аят 26)."]]],["p","<b><i>Они придут к Ибрахиму и скажут: \"О Ибрахим! Ты – пророк Аллаха и Его любимец (халиль) из числа живших на земле. Заступись же за нас пред твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". Ибрахим скажет им: \"Поистине, мой Господь сегодня разгневался так, как не гневался Он никогда раньше и не будет гневаться уже никогда больше\". После этого он упомянет, как солгал (в земной жизни), и скажет: \"Сам я, сам я (нуждаюсь в защите). Вы же ступайте к другому. Ступайте к Мусе\".</i></b>"],["p","<b><i>Они придут к Мусе и скажут: \"О Муса! Ты – посланник Аллаха, и Аллах отдал тебе предпочтение перед другими людьми, (ибо Он передал тебе) Своё послание и говорил с тобой (без посредников). Заступись же за нас пред твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". Муса скажет им: \"Поистине, мой Господь сегодня разгневался так, как не гневался Он никогда раньше и не будет гневаться уже никогда больше. Что же касается меня, то я убил человека, убивать которого мне велено не было</i></b><sup class=\"fn\">667</sup>. <b><i>Сам я, сам я (нуждаюсь в защите). Вы же ступайте к другому. Ступайте к ′Исе, сыну Марьям\".</i></b>"],["n",[[667,"Всевышний Аллах сказал: <b>«Войдя в город, когда его жители были невнимательны, он</b> [Муса]<b> встретил двух мужчин, которые дрались друг с другом. Один был из числа его сторонников, а другой был из числа его врагов. Тот, кто был из числа его сторонников, попросил его помочь ему против того, кто был из числа его врагов. Муса ударил его кулаком и прикончил. Он сказал: \"Это - одно из деяний шайтана. Воистину, он является явным врагом, вводящим в заблуждение\"».</b> (Сура «аль-Касас», аят 15)."]]],["p","<b><i>Они придут к ′Исе, сыну Марьям, и скажут: \"О ′Иса! Ты – посланник Аллаха, и ты говорил с людьми ещё в колыбели, и ты – Его слово, которое Он даровал Марьям, и дух от Него. Заступись же за нас пред твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". ′Иса скажет им: \"Поистине, мой Господь сегодня разгневался так, как не гневался Он никогда раньше и не будет гневаться уже никогда больше\", но не станет упоминать о каких-либо своих грехах, \"Сам я, сам я (нуждаюсь в защите). Вы же ступайте к другому. Ступайте к Мухаммаду\". </i></b>"]],[["p","<b><i>И вот (люди) придут ко мне и скажут: \"О Мухаммад! Ты – посланник Аллаха и последний из пророков. И Аллах простил тебе все прошлые и будущие грехи. Заступись же за нас пред твоим Господом! Разве не видишь ты, в каком мы положении, и разве не видишь ты, что нас постигло?!\". </i></b>"],["p","<b><i>Тогда я подойду и остановлюсь у трона, и склонюсь в земном поклоне перед моим Господом, после чего Аллах откроет и внушит мне такие слова восхваления и прославления Его, каких никому до меня не внушал. А потом Он скажет: \"О Мухаммад! Подними свою голову. Проси, и будет даровано тебе, заступайся, и твоё заступничество будет принято\". Я подниму голову и скажу: \"Господь мой! Моя община! Моя община! Моя община!\". Будет сказано: \"О Мухаммад! Введи в Рай тех членов твоей общины, которые освобождены от расчёта, через правые врата Рая, но они могут входить вместе с людьми и через другие врата\". </i></b>"],["p","<b><i>Клянусь Тем, в Чьей руке моя душа! Поистине, расстояние между створками каждых врат Рая равно расстоянию между Меккой и Хаджаром (или Меккой и Бусрой)»</i></b><sup class=\"fn\">668</sup>."],["n",[[668,"Аль-Бухари, 4712; Муслим, 194; ат-Тирмизи, 2434; Ахмад, 2/435."]]],["p","ГЛАВА 52: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, ЧТО ЭТО ЗАСТУПНИЧЕСТВО, ОПИСАННОЕ НАМИ, КАК ПЕРВОЕ ЗАСТУПНИЧЕСТВО НАШЕГО ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), ЯВЛЯЕТСЯ ТЕМ, ВО ВРЕМЯ КОТОРОГО ОН ПОПРОСИТ, ЧТОБЫ АЛЛАХ ПРОВЁЛ СУД МЕЖДУ ТВОРЕНИЯМИ."],["p","Именно тогда Всемогущий и Великий Аллах прикажет ему ввести в Рай через правые врата тех людей из его общины, которые будут освобождены от расчёта. И он первым среди всех верующих войдёт в Рай."],["p","519-520 ― ′Абдуллах ибн ′Умар (да будет доволен Аллах им и его отцом) слышал, как посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Человек будет просить людей</i></b><sup class=\"fn\">669</sup><b><i> до тех пор, пока не придёт в День Воскресения без единого кусочка плоти на лице»</i></b><sup class=\"fn\">670</sup><b><i>. </i></b>"],["n",[[669,"Речь идёт о каждом, кто не имеет на это права, поскольку располагает необходимыми средствами."],[670,"Аль-Бухари, 1474; Муслим, 1040; Ахмад, 2/15, 88; ан-Насаи в «ас-Сунан аль-кубра», 2366; ат-Табарани в «аль-Аусат», 8725, и др."]]],["p","521 ― Также пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, в День Воскресения солнце приблизится к людям настолько, что пот дойдёт до середины уха (некоторых из них). И оказавшись в подобном положении, они попросят о помощи Адама, но он скажет: \"Я – не для этого!\". Затем они попросят о помощи Мусу, но он ответит то же самое. Затем они попросят о помощи Мухаммада, и он станет заступаться, дабы (Аллах) провёл суд между творениями. Он пойдёт и схватится за кольцо райских (врат), и вот тогда Аллах возведёт его на достохвальное место</i></b><sup class=\"fn\">671</sup><b><i>. Его будут хвалить все те, кто соберётся в этом месте»</i></b><sup class=\"fn\">672</sup>."],["n",[[671,"Всевышний Аллах сказал: <b>«Бодрствуй часть ночи, читая Коран во время дополнительных молитв. Быть может, Господь твой возведет тебя на Достохвальное место». </b>(Сура «аль-Исра», аят 79)."],[672,"Аль-Бухари, 1475; Ибн Манда в «аль-Иман», 884; Ибн Джарир в «Тафсире», 8/129; ат-Табарани в «аль-Аусат», 8725."]]]]];
